// JAH demo program — Plan scoring demo
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function score(plan){ return plan.steps*2+plan.clarity*5-plan.cost; }
var plans=[{steps:3,clarity:8,cost:10},{steps:5,clarity:9,cost:6},{steps:2,clarity:5,cost:4}];
var best=plans.reduce(function(a,b){return score(a)>score(b)?a:b;});
check("best plan has 5 steps", best.steps, 5);
check("score computed", score(best), 49);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

