// JAH demo program — Trend with context
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function trend(vals){ var n=vals.length, sx=0, sy=0, sxx=0, sxy=0;
  for(var i=0;i<n;i++){ sx+=i; sy+=vals[i]; sxx+=i*i; sxy+=i*vals[i]; }
  return (n*sxy-sx*sy)/(n*sxx-sx*sx); }
